}

crumb-club-thumbnail.source:
/**
 * Crumb Club (a fictional baking channel) needs a thumbnail: a YouTube thumbnail, 1280 by 720.
 *
 * Made to be read at the size of a stamp: three lines of condensed capitals, each on a black
 * block, over tomato red with rays behind a loaf, and a yellow sticker for the day count. The
 * rays and the loaf are one Svg under the words, in a Layer.
 */
import type { ReactNode } from "react";
import { Canvas, Circle, Column, Ellipse, Heading, Layer, Path, Polygon, Row, Svg, Text } from "@hyper-elements/react";

const TOMATO = "#E8392C";
const RAY = "#F0574A";
const YELLOW = "#FFE14D";
const BLACK = "#141414";
const CRUST = "#B8692E";
const BAKED = "#DE9A52";
const FLOUR = "#F6E7CF";

const TALL = "Anton, Impact, 'Arial Narrow', sans-serif";
const SANS = "Poppins, 'Helvetica Neue', Arial, sans-serif";

/** Rays from (940, 400) out past the edges, every other one drawn. */
const RAYS = Array.from({ length: 12 }, (_, i) => {
  const a = (i * Math.PI) / 6;
  const b = a + Math.PI / 12;
  const far = 1100;
  return `940,400 ${940 + Math.cos(a) * far},${400 + Math.sin(a) * far} ${940 + Math.cos(b) * far},${400 + Math.sin(b) * far}`;
});

/** A line centered in its row, at its own width: how an image centers text, the same in its HTML. */
const centered = (line: ReactNode) => <Row style={{ justifyContent: "center" }}>{line}</Row>;

/** A line of the title: its own width, on a black block. */
const line = (text: string, color: string) => (
  <Row>
    <Heading level={1} style={{ flex: "none", backgroundColor: BLACK, color, fontFamily: TALL, fontWeight: 400, fontSize: 116, lineHeight: 1.05, padding: [6, 24, 0, 24] }}>
      {text}
    </Heading>
  </Row>
);

export default function CrumbClubThumbnail() {
  return (
    <Canvas
      width={1280}
      height={720}
      lang="en"
      title="Crumb Club: I baked bread for 30 days"
      fonts={[
        { family: "Anton", src: "https://fonts.gstatic.com/s/anton/v27/1Ptgg87LROyAm3Kz-C8CSKlv.woff2", format: "woff2", weight: 400 },
        { family: "Poppins", src: "https://fonts.gstatic.com/s/poppins/v24/pxiByp8kv8JHgFVrLCz7Z1xlFd2JQEk.woff2", format: "woff2", weight: 700 },
      ]}
      style={{ backgroundColor: TOMATO, color: "#FFFFFF", fontFamily: SANS }}
    >
      <Layer style={{ height: 720 }}>
        <Svg width={1280} height={720} title="A golden loaf of bread with three cuts across its top, in front of red rays.">
          {RAYS.map((points) => (
            <Polygon key={points} points={points} style={{ fill: RAY }} />
          ))}
          <Ellipse cx={940} cy={560} rx={260} ry={34} style={{ fill: BLACK, opacity: 0.25 }} />
          {/* The loaf: its crust, its baked top, the cuts, and flour dusted on. */}
          <Path d="M700 540 C690 380 800 300 940 300 C1080 300 1190 380 1180 540 Z" style={{ fill: CRUST }} />
          <Path d="M722 520 C716 392 812 322 940 322 C1068 322 1164 392 1158 520 Z" style={{ fill: BAKED }} />
          <Path d="M820 360 C850 400 870 440 880 490" style={{ stroke: FLOUR, strokeWidth: 12, fill: "transparent" }} />
          <Path d="M930 340 C955 390 970 440 975 500" style={{ stroke: FLOUR, strokeWidth: 12, fill: "transparent" }} />
          <Path d="M1040 360 C1060 400 1070 440 1072 490" style={{ stroke: FLOUR, strokeWidth: 12, fill: "transparent" }} />
          {[[790, 430], [1010, 380], [1110, 460], [900, 470]].map(([cx, cy]) => (
            <Circle key={`${cx}-${cy}`} cx={cx} cy={cy} r={5} style={{ fill: FLOUR, opacity: 0.8 }} />
          ))}
        </Svg>
        <Row style={{ height: 720, padding: [64, 56, 56, 64] }}>
          <Column style={{ height: 600, justifyContent: "space-between" }}>
            <Column style={{ gap: 12 }}>
              {line("I BAKED", "#FFFFFF")}
              {line("BREAD FOR", "#FFFFFF")}
              {line("30 DAYS", YELLOW)}
            </Column>
            <Text style={{ fontFamily: SANS, fontWeight: 700, fontSize: 28, letterSpacing: 4, textTransform: "uppercase" }}>Crumb Club</Text>
          </Column>
          <Column style={{ flex: "none", width: 220, alignItems: "end" }}>
            <Column style={{ width: 200, height: 200, borderRadius: 100, backgroundColor: YELLOW, border: `6px solid ${BLACK}`, justifyContent: "center", color: BLACK }}>
              {centered(<Text style={{ flex: "none", fontWeight: 700, fontSize: 26, letterSpacing: 3, lineHeight: 1 }}>DAY</Text>)}
              {centered(<Text style={{ flex: "none", fontFamily: TALL, fontSize: 96, lineHeight: 1 }}>30</Text>)}
            </Column>
          </Column>
        </Row>
      </Layer>
    </Canvas>
  );
}

fernway-spring-sale.source:
/**
 * Fernway (a fictional flower shop) announces a spring sale: an Instagram post, 1080 by 1080.
 *
 * Loud and friendly: a hot pink square, flowers drawn as rings of circles in its corners, "Spring"
 * in a marker hand over SALE in tall condensed capitals, and the offer in a butter-yellow pill.
 * The flowers are one Svg under the words, in a Layer.
 */
import type { ReactNode } from "react";
import { Canvas, Circle, Column, Heading, Layer, Path, Row, Svg, Text } from "@hyper-elements/react";

const PINK = "#FF5C8A";
const BUTTER = "#FFD84D";
const LEAF = "#2F9E6E";
const BLUSH = "#FFC2D4";
const INK = "#2B1B24";
const WHITE = "#FFFFFF";

const SCRIPT = "Caveat, 'Comic Sans MS', cursive";
const TALL = "Anton, Impact, 'Arial Narrow', sans-serif";
const SANS = "Poppins, 'Helvetica Neue', Arial, sans-serif";

/** A flower seen from above: six petals in a ring, and its middle. */
const flower = (cx: number, cy: number, r: number, petal: string, middle: string) => (
  <>
    {Array.from({ length: 6 }, (_, i) => {
      const a = (i * Math.PI) / 3;
      return <Circle key={i} cx={cx + Math.cos(a) * r} cy={cy + Math.sin(a) * r} r={r * 0.78} style={{ fill: petal }} />;
    })}
    <Circle cx={cx} cy={cy} r={r * 0.62} style={{ fill: middle }} />
  </>
);

/** A line centered in its row, at its own width: how an image centers text, the same in its HTML. */
const centered = (line: ReactNode) => <Row style={{ justifyContent: "center" }}>{line}</Row>;

/** A pill around a few words. */
const pill = (text: string, style: object) => centered(<Text style={{ flex: "none", borderRadius: 999, ...style }}>{text}</Text>);

export default function FernwaySpringSale() {
  return (
    <Canvas
      width={1080}
      height={1080}
      lang="en"
      title="Fernway spring sale: 30% off every bouquet, this weekend only"
      fonts={[
        { family: "Anton", src: "https://fonts.gstatic.com/s/anton/v27/1Ptgg87LROyAm3Kz-C8CSKlv.woff2", format: "woff2", weight: 400 },
        { family: "Caveat", src: "https://fonts.gstatic.com/s/caveat/v23/WnznHAc5bAfYB2QRah7pcpNvOx-pjSx6eIWpYT5Kmgq3sw.woff2", format: "woff2", weight: 600 },
        { family: "Poppins", src: "https://fonts.gstatic.com/s/poppins/v24/pxiByp8kv8JHgFVrLGT9Z1xlFd2JQEk.woff2", format: "woff2", weight: 500 },
        { family: "Poppins", src: "https://fonts.gstatic.com/s/poppins/v24/pxiByp8kv8JHgFVrLCz7Z1xlFd2JQEk.woff2", format: "woff2", weight: 700 },
      ]}
      style={{ backgroundColor: PINK, color: WHITE, fontFamily: SANS, textAlign: "center" }}
    >
      <Layer style={{ height: 1080, alignItems: "center" }}>
        <Svg width={1080} height={1080} title="Flowers in pink, yellow and white in the corners of a pink square, with leaves.">
          {/* Leaves first, so the flowers sit on them. */}
          <Path d="M0 840 C120 800 230 860 260 1080 L0 1080 Z" style={{ fill: LEAF }} />
          <Path d="M1080 250 C960 230 880 140 900 0 L1080 0 Z" style={{ fill: LEAF }} />
          <Circle cx={540} cy={1180} r={260} style={{ fill: BLUSH, opacity: 0.45 }} />
          {flower(150, 150, 70, BUTTER, "#FF8A3D")}
          {flower(330, 70, 34, WHITE, BUTTER)}
          {flower(960, 360, 46, WHITE, BUTTER)}
          {flower(110, 930, 62, BLUSH, BUTTER)}
          {flower(270, 1010, 34, BUTTER, "#FF8A3D")}
          {flower(940, 900, 92, BUTTER, "#FF8A3D")}
          {flower(780, 1010, 38, WHITE, BUTTER)}
          {/* Confetti. */}
          {[[460, 120], [640, 90], [860, 140], [70, 520], [1010, 600], [620, 990], [420, 960]].map(([cx, cy]) => (
            <Circle key={`${cx}-${cy}`} cx={cx} cy={cy} r={9} style={{ fill: WHITE, opacity: 0.8 }} />
          ))}
        </Svg>
        <Column style={{ height: 1080, padding: [0, 120], justifyContent: "center", gap: 18 }}>
          {centered(<Text style={{ flex: "none", fontWeight: 700, fontSize: 24, letterSpacing: 6, textTransform: "uppercase" }}>Fernway Flowers</Text>)}
          <Column>
            {centered(<Text style={{ flex: "none", fontFamily: SCRIPT, fontWeight: 600, fontSize: 150, lineHeight: 0.9, color: BUTTER }}>Spring</Text>)}
            {centered(
              <Heading level={1} style={{ flex: "none", fontFamily: TALL, fontWeight: 400, fontSize: 300, lineHeight: 0.92, letterSpacing: 6 }}>
                SALE
              </Heading>,
            )}
          </Column>
          {pill("30% off every bouquet", { backgroundColor: BUTTER, color: INK, fontWeight: 700, fontSize: 38, padding: [14, 36] })}
          {centered(<Text style={{ flex: "none", fontWeight: 500, fontSize: 26 }}>This weekend only · fernway.shop</Text>)}
        </Column>
      </Layer>
    </Canvas>
  );
}

gridline-workshop-banner.source:
/**
 * Gridline (a fictional design tool) announces a live workshop: a LinkedIn event banner, 1200 by 627.
 *
 * Deep violet with a grid of shapes on the right, squares and circles and quarter-circles in lime,
 * pink and white, like a component library laid out. The title in a chunky grotesque, the details
 * in pills, and the two hosts as initials in circles. The grid is one Svg under the words, in a Layer.
 */
import { Canvas, Circle, Column, Heading, Layer, Path, Rect, Row, Svg, Text } from "@hyper-elements/react";

const VIOLET = "#3B1FA8";
const DEEP = "#2A1380";
const LIME = "#C6F36B";
const PINK = "#FF8FCF";
const WHITE = "#FFFFFF";
const SOFT = "#CFC6F5";

const GROTESK = "'Bricolage Grotesque', 'Helvetica Neue', Arial, sans-serif";
const SANS = "Poppins, 'Helvetica Neue', Arial, sans-serif";

/** The grid's cells, 4 across and 5 down from (760, 0), each 110 square: what's drawn in each. */
const CELL = 110;
const SHAPES = ["square", "circle", "quarter", "none", "circle", "quarter", "square", "circle", "none", "square", "circle", "quarter", "quarter", "circle", "none", "square", "circle", "square", "quarter", "circle"] as const;
const FILLS = [LIME, PINK, WHITE, LIME, PINK, WHITE, PINK, LIME, WHITE, PINK, LIME, PINK, WHITE, LIME, PINK, LIME, WHITE, PINK, LIME, PINK];

const shape = (i: number) => {
  const x = 760 + (i % 4) * CELL;
  const y = (Math.floor(i / 4)) * CELL + 40;
  const fill = FILLS[i];
  const pad = 14;
  switch (SHAPES[i]) {
    case "square":
      return <Rect key={i} x={x + pad} y={y + pad} width={CELL - pad * 2} height={CELL - pad * 2} rx={14} style={{ fill }} />;
    case "circle":
      return <Circle key={i} cx={x + CELL / 2} cy={y + CELL / 2} r={CELL / 2 - pad} style={{ fill }} />;
    case "quarter":
      return <Path key={i} d={`M${x + pad} ${y + CELL - pad} L${x + pad} ${y + pad} A${CELL - pad * 2} ${CELL - pad * 2} 0 0 1 ${x + CELL - pad} ${y + CELL - pad} Z`} style={{ fill }} />;
    default:
      return null;
  }
};

/** A detail in a pill: its own width. */
const pill = (text: string, style: object = {}) => (
  <Text style={{ flex: "none", border: `2px solid ${SOFT}`, borderRadius: 999, padding: [8, 20], fontWeight: 500, fontSize: 20, ...style }}>{text}</Text>
);

/** A host: their initials in a circle, and their name and role. */
const host = (initials: string, color: string, name: string, role: string) => (
  <Row style={{ width: 280, gap: 14, alignItems: "center" }}>
    <Column style={{ width: 60, height: 60, borderRadius: 30, backgroundColor: color, justifyContent: "center", color: DEEP }}>
      <Row style={{ justifyContent: "center" }}>
        <Text style={{ flex: "none", fontWeight: 700, fontSize: 20, lineHeight: 1 }}>{initials}</Text>
      </Row>
    </Column>
    <Column>
      <Text style={{ fontWeight: 700, fontSize: 19, lineHeight: 1.3 }}>{name}</Text>
      <Text style={{ fontWeight: 500, fontSize: 16, lineHeight: 1.3, color: SOFT }}>{role}</Text>
    </Column>
  </Row>
);

export default function GridlineWorkshopBanner() {
  return (
    <Canvas
      width={1200}
      height={627}
      lang="en"
      title="Gridline live workshop: Design systems that don't break. Thursday 20 November, 5pm GMT"
      fonts={[
        { family: "Bricolage Grotesque", src: "https://fonts.gstatic.com/s/bricolagegrotesque/v9/3y9H6as8bTXq_nANBjzKo3IeZx8z6up5BeSl5jBNz_19PpbpMXuECpwUxJBOm_OJWiawA1XphjhQYg.woff2", format: "woff2", weight: "400 800" },
        { family: "Poppins", src: "https://fonts.gstatic.com/s/poppins/v24/pxiByp8kv8JHgFVrLGT9Z1xlFd2JQEk.woff2", format: "woff2", weight: 500 },
        { family: "Poppins", src: "https://fonts.gstatic.com/s/poppins/v24/pxiByp8kv8JHgFVrLCz7Z1xlFd2JQEk.woff2", format: "woff2", weight: 700 },
      ]}
      style={{ backgroundColor: VIOLET, color: WHITE, fontFamily: SANS }}
    >
      <Layer style={{ height: 627 }}>
        <Svg width={1200} height={627} title="A grid of lime, pink and white squares, circles and quarter-circles on the right.">
          <Rect x={740} y={0} width={460} height={627} style={{ fill: DEEP }} />
          {SHAPES.map((_, i) => shape(i))}
        </Svg>
        <Column style={{ height: 627, width: 700, padding: [56, 0, 56, 64], justifyContent: "space-between" }}>
          <Column style={{ gap: 26 }}>
            <Row>
              <Text style={{ flex: "none", backgroundColor: LIME, color: DEEP, fontWeight: 700, fontSize: 18, letterSpacing: 3, textTransform: "uppercase", padding: [8, 18], borderRadius: 999 }}>
                Live workshop
              </Text>
            </Row>
            <Heading level={1} style={{ fontFamily: GROTESK, fontWeight: 800, fontSize: 76, lineHeight: 1, letterSpacing: -2 }}>
              Design systems that don't break
            </Heading>
            <Text style={{ fontWeight: 500, fontSize: 22, lineHeight: 1.45, color: SOFT, maxWidth: 560 }}>
              Forty-five minutes on tokens, variants and naming, with questions at the end.
            </Text>
            <Row style={{ gap: 10 }}>
              {pill("Thu 20 Nov")}
              {pill("5pm GMT")}
              {pill("Free", { backgroundColor: WHITE, color: DEEP, border: `2px solid ${WHITE}`, fontWeight: 700 })}
            </Row>
          </Column>
          <Row style={{ gap: 36, alignItems: "center" }}>
            {host("AO", LIME, "Ama Owusu", "Design lead, Gridline")}
            {host("JP", PINK, "Jonas Petrov", "Staff engineer")}
          </Row>
        </Column>
      </Layer>
    </Canvas>
  );
}

keel-sign-in-code.source:
/**
 * Keel (a fictional bank) sends a sign-in code.
 *
 * A security message should look like nothing but itself: a narrow column, the system's own font
 * (it's already on the phone, so nothing loads before the code shows), the code large in DM Mono
 * so no digit can be mistaken for another, and who asked for it. One deep green, for the bank's
 * mark and the way out if it wasn't you.
 */
import { Column, Email, Heading, Link, Text, Row, Section, Span, Table, TableCell, TableRow } from "@hyper-elements/react";

const INK = "#0B0D0C";
const QUIET = "#5A5F5C";
const RULE = "#E2E4E2";
const PANEL = "#F3F4F2";
const GREEN = "#0F5C45";

const SYSTEM = "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif";
const MONO = "'DM Mono', SFMono-Regular, Menlo, Consolas, monospace";

const SITE = "https://keel.example";

/** A line of who asked for the code. */
const asked = (name: string, value: string, last = false) => (
  <TableRow>
    <TableCell style={{ width: 96, padding: [10, 12, 10, 0], color: QUIET, verticalAlign: "top", border: last ? undefined : { bottom: `1px solid ${RULE}` } }}>{name}</TableCell>
    <TableCell style={{ padding: [10, 0], verticalAlign: "top", border: last ? undefined : { bottom: `1px solid ${RULE}` } }}>{value}</TableCell>
  </TableRow>
);

export default function KeelSignInCode() {
  return (
    <Email
      width={480}
      lang="en-GB"
      title="Your Keel sign-in code"
      previewText="482 913 is your code to sign in to Keel. It works once, for ten minutes."
      fonts={[{ family: "DM Mono", src: "https://fonts.gstatic.com/s/dmmono/v16/aFTR7PB1QTsUX8KYvumzEYOtbYf-Vlg.woff2", format: "woff2", weight: 500 }]}
      style={{ backgroundColor: "#FFFFFF", color: INK, fontFamily: SYSTEM, fontSize: 16, lineHeight: 1.55 }}
    >
      <Section style={{ padding: [48, 24, 56], gap: 32 }} mobile={{ padding: [32, 24, 40], gap: 28 }}>
        <Text style={{ fontSize: 22, fontWeight: 700, letterSpacing: -0.6, lineHeight: 1 }}>
          <Link href={SITE} style={{ color: INK, textDecoration: "none" }}>
            keel<Span style={{ color: GREEN }}>.</Span>
          </Link>
        </Text>

        <Column style={{ gap: 10 }}>
          <Heading level={1} style={{ fontSize: 26, fontWeight: 600, lineHeight: 1.2, letterSpacing: -0.4 }}>
            Your sign-in code
          </Heading>
          <Text style={{ color: QUIET }}>Enter it in the Keel app to finish signing in. It works once, for the next ten minutes.</Text>
        </Column>

        <Column style={{ backgroundColor: PANEL, borderRadius: 10, padding: [26, 28], gap: 6 }} mobile={{ padding: [22, 20] }}>
          <Text style={{ fontFamily: MONO, fontSize: 46, fontWeight: 500, letterSpacing: 10, lineHeight: 1.1 }} mobile={{ fontSize: 40, letterSpacing: 8 }}>
            482 913
          </Text>
          <Text style={{ fontSize: 13, color: QUIET }}>Expires at 06:52 GMT</Text>
        </Column>

        <Column style={{ gap: 8 }}>
          <Text style={{ fontSize: 13, fontWeight: 600, color: QUIET }}>Who asked for it</Text>
          <Table style={{ fontSize: 15, lineHeight: 1.45, border: { top: `1px solid ${RULE}`, bottom: `1px solid ${RULE}` } }}>
            {asked("Device", "Safari on a Mac")}
            {asked("Near", "Lisbon, Portugal")}
            {asked("When", "06:42 GMT, Friday 6 November", true)}
          </Table>
        </Column>

        <Row stackOnMobile={false} style={{ gap: 14, padding: [0, 0, 0, 14], border: { left: `2px solid ${GREEN}` } }}>
          <Column style={{ gap: 6 }}>
            <Text style={{ fontWeight: 600 }}>Not you?</Text>
            <Text style={{ fontSize: 15, color: QUIET }}>
              Don’t share this code with anyone, even someone who says they’re from Keel. Freeze your cards in the app, or call us any time on{" "}
              <Link href="tel:+448081570412" style={{ color: GREEN, fontWeight: 600 }}>
                0808 157 0412
              </Link>
              .
            </Text>
          </Column>
        </Row>

        <Text style={{ fontSize: 13, lineHeight: 1.6, color: QUIET, padding: [24, 0, 0], border: { top: `1px solid ${RULE}` } }}>
          We’ll never ask for this code by phone, email or text. Keel Bank Ltd, 12 Lantern Yard, London E1 6QL.
        </Text>
      </Section>
    </Email>
  );
}

morning-pages-quote.source:
/**
 * Morning Pages (a fictional journaling app) posts its quote of the week: an Instagram portrait
 * post, 1080 by 1350.
 *
 * Soft and warm: oat paper, a terracotta quote mark, the quote in a tall italic serif, and a sun
 * setting behind a sage arch in the corner. The arch and sun are one Svg under the words, in a Layer.
 */
import { Canvas, Circle, Column, Heading, Layer, Path, Polygon, Rect, Row, Svg, Text } from "@hyper-elements/react";

const OAT = "#F6EEE3";
const INK = "#2E2A26";
const QUIET = "#7A6F64";
const CLAY = "#D9653B";
const SAGE = "#9DB59A";
const SUN = "#F2A541";

const SERIF = "'Playfair Display', Georgia, serif";
const SANS = "Poppins, 'Helvetica Neue', Arial, sans-serif";

/** A four-pointed sparkle, centered on (x, y). */
const sparkle = (x: number, y: number, r: number) =>
  `${x},${y - r} ${x + r * 0.22},${y - r * 0.22} ${x + r},${y} ${x + r * 0.22},${y + r * 0.22} ${x},${y + r} ${x - r * 0.22},${y + r * 0.22} ${x - r},${y} ${x - r * 0.22},${y - r * 0.22}`;

export default function MorningPagesQuote() {
  return (
    <Canvas
      width={1080}
      height={1350}
      lang="en"
      title="Morning Pages, quote of the week: Small steps, taken daily, become the path."
      fonts={[
        { family: "Playfair Display", src: "https://fonts.gstatic.com/s/playfairdisplay/v40/nuFRD-vYSZviVYUb_rj3ij__anPXDTnCjmHKM4nYO7KN_pqTXtHA-X-uE0qEEw.woff2", format: "woff2", weight: 500, style: "italic" },
        { family: "Poppins", src: "https://fonts.gstatic.com/s/poppins/v24/pxiByp8kv8JHgFVrLGT9Z1xlFd2JQEk.woff2", format: "woff2", weight: 500 },
        { family: "Poppins", src: "https://fonts.gstatic.com/s/poppins/v24/pxiByp8kv8JHgFVrLCz7Z1xlFd2JQEk.woff2", format: "woff2", weight: 700 },
      ]}
      style={{ backgroundColor: OAT, color: INK, fontFamily: SANS }}
    >
      <Layer style={{ height: 1350 }}>
        <Svg width={1080} height={1350} title="A sun setting behind a sage-green arch in the bottom right corner, with two small sparkles.">
          <Circle cx={830} cy={1040} r={150} style={{ fill: SUN }} />
          {/* The arch: a rectangle with a round top, cut by the bottom edge. */}
          <Path d="M640 1350 L640 1150 A200 200 0 0 1 1040 1150 L1040 1350 Z" style={{ fill: SAGE }} />
          <Rect x={640} y={1288} width={400} height={62} style={{ fill: "#87A184" }} />
          <Polygon points={sparkle(560, 1080, 30)} style={{ fill: CLAY }} />
          <Polygon points={sparkle(940, 860, 18)} style={{ fill: CLAY }} />
        </Svg>
        <Column style={{ height: 1350, padding: [110, 100], justifyContent: "space-between" }}>
          <Column style={{ gap: 64 }}>
            <Row style={{ alignItems: "center", justifyContent: "space-between" }}>
              <Text style={{ flex: "none", backgroundColor: INK, color: OAT, fontWeight: 700, fontSize: 22, letterSpacing: 1, padding: [10, 24], borderRadius: 999 }}>
                @morningpages
              </Text>
              <Text style={{ flex: "none", fontWeight: 500, fontSize: 22, letterSpacing: 4, textTransform: "uppercase", color: QUIET }}>Quote of the week</Text>
            </Row>
            <Column style={{ gap: 28 }}>
              <Text style={{ fontFamily: SERIF, fontStyle: "italic", fontWeight: 500, fontSize: 240, lineHeight: 0.5, color: CLAY, padding: [64, 0, 0, 0] }}>“</Text>
              <Heading level={1} style={{ fontFamily: SERIF, fontStyle: "italic", fontWeight: 500, fontSize: 92, lineHeight: 1.08, letterSpacing: -1, maxWidth: 820 }}>
                Small steps, taken daily, become the path.
              </Heading>
              <Text style={{ fontWeight: 700, fontSize: 24, letterSpacing: 4, textTransform: "uppercase", color: CLAY }}>— Morning Pages</Text>
            </Column>
          </Column>
          <Text style={{ fontWeight: 500, fontSize: 24, color: QUIET }}>morningpages.app · Write a page today</Text>
        </Column>
      </Layer>
    </Canvas>
  );
}

oyen-launch.source:
/**
 * Oyen (a fictional maker of audio instruments) announces its FR-2 field recorder.
 *
 * Warm drafting paper, near-black ink and one signal orange, used only where the eye should land:
 * the drawing's callouts, the main button, and one closing band. Geist for words, Geist Mono for
 * labels and numbers. A rail of labels at the left and a content column make the grid, and the
 * technical drawing's numbered callouts are the list under it.
 */
import type { ReactNode } from "react";
import { Button, Column, Email, Heading, Image, Link, Text, Row, Section, Table, TableCell, TableRow } from "@hyper-elements/react";

const PAPER = "#F3F1EC";
const INK = "#1A1917";
const QUIET = "#5F5B53";
const RULE = "#D3CEC4";
const SIGNAL = "#FF5B1F";
const SIGNAL_DOWN = "#E8490F";

const SANS = "Geist, 'Helvetica Neue', Helvetica, Arial, sans-serif";
const MONO = "'Geist Mono', SFMono-Regular, Menlo, Consolas, monospace";

const SITE = "https://oyen.example";

const DRAWING =
  "A technical drawing of FR-2 from the front and the side: two capsules at 90 degrees on top, a display, a large dial, and play, stop and record buttons. It is 132 by 68 by 24 millimetres.";

/** Small mono capitals: section labels, metadata, the figure's caption. */
const label = { fontFamily: MONO, fontSize: 12, lineHeight: 1.5, letterSpacing: 1.2, textTransform: "uppercase", color: QUIET } as const;

/** The rail: a part's label at the left, under a rule, and its content beside it (above it on phones). */
const RAIL = 136;
const railed = (name: string, content: ReactNode) => (
  <Row style={{ gap: 24, padding: [14, 0, 0], border: { top: `1px solid ${INK}` } }} mobile={{ gap: 20 }}>
    <Column style={{ width: RAIL }}>
      <Text style={{ ...label, color: INK }}>{name}</Text>
    </Column>
    <Column>{content}</Column>
  </Row>
);

/** One of the drawing's callouts: its number in an orange disc, what it is, and why it matters. */
const callout = (n: number, title: string, body: string) => (
  <Row stackOnMobile={false} style={{ gap: 16, padding: n === 1 ? [0, 0, 20] : [20, 0], border: n === 1 ? undefined : { top: `1px solid ${RULE}` } }}>
    <Column style={{ width: 24 }}>
      <Text style={{ width: 24, backgroundColor: SIGNAL, borderRadius: 12, fontFamily: MONO, fontSize: 12, fontWeight: 500, lineHeight: "24px", textAlign: "center", color: INK }}>{String(n)}</Text>
    </Column>
    <Column style={{ gap: 4 }}>
      <Heading level={3} style={{ fontSize: 17, fontWeight: 600, lineHeight: "24px", letterSpacing: -0.2 }}>
        {title}
      </Heading>
      <Text style={{ fontSize: 15, lineHeight: 1.55, color: QUIET }}>{body}</Text>
    </Column>
  </Row>
);

/** A line of the spec sheet: a mono label, and the value in the text face. */
const spec = (name: string, value: string, first = false) => (
  <TableRow>
    <TableCell style={{ width: 100, verticalAlign: "top", padding: first ? [0, 12, 10, 0] : [10, 12, 10, 0], fontFamily: MONO, fontSize: 12, lineHeight: "21px", letterSpacing: 0.6, textTransform: "uppercase", color: QUIET }}>
      {name}
    </TableCell>
    <TableCell style={{ verticalAlign: "top", padding: first ? [0, 0, 10] : [10, 0] }}>{value}</TableCell>
  </TableRow>
);

export default function OyenLaunch() {
  return (
    <Email
      width={600}
      lang="en"
      title="FR-2 is here"
      previewText="A pocket recorder with capsules that turn, one dial, and nothing to set. €349, ships 2 December."
      fonts={[
        { family: "Geist", src: "https://fonts.gstatic.com/s/geist/v5/gyByhwUxId8gMEwcGFWNOITd.woff2", format: "woff2", weight: "100 900" },
        { family: "Geist Mono", src: "https://fonts.gstatic.com/s/geistmono/v6/or3nQ6H-1_WfwkMZI_qYFrcdmhHkjko.woff2", format: "woff2", weight: "100 900" },
      ]}
      style={{ backgroundColor: PAPER, color: INK, fontFamily: SANS, fontSize: 16, lineHeight: 1.6 }}
    >
      <Section style={{ padding: [36, 48, 72], gap: 64 }} mobile={{ padding: [28, 24, 56], gap: 48 }}>
        {/* Masthead */}
        <Row stackOnMobile={false} style={{ alignItems: "end", padding: [0, 0, 14], border: { bottom: `1px solid ${INK}` } }}>
          <Column style={{ width: 120 }}>
            <Text style={{ fontSize: 19, fontWeight: 700, letterSpacing: 5, lineHeight: "20px" }}>
              <Link href={SITE} style={{ color: INK, textDecoration: "none" }}>
                OYEN
              </Link>
            </Text>
          </Column>
          <Column>
            <Text style={{ ...label, lineHeight: "18px", textAlign: "right" }}>Dispatch 07 · Nov 2026</Text>
          </Column>
        </Row>

        {/* The announcement */}
        <Column style={{ gap: 28 }} mobile={{ gap: 24 }}>
          <Column style={{ gap: 20 }}>
            <Text style={label}>New instrument — FR-2</Text>
            <Heading level={1} style={{ fontSize: 62, lineHeight: 1, letterSpacing: -2.6, fontWeight: 500 }} mobile={{ fontSize: 44, letterSpacing: -1.8 }}>
              Record the room you’re in.
            </Heading>
          </Column>
          <Text style={{ fontSize: 19, lineHeight: 1.5, maxWidth: 400 }} mobile={{ fontSize: 17 }}>
            FR-2 is a pocket recorder with two capsules that turn, one dial, and nothing to set before you press record.
          </Text>
          <Row style={{ alignItems: "center", gap: 20 }} mobile={{ gap: 14 }}>
            <Button
              href={`${SITE}/fr-2`}
              style={{ width: 184, backgroundColor: SIGNAL, color: INK, fontSize: 15, fontWeight: 600, padding: [16, 0], borderRadius: 2 }}
              hover={{ backgroundColor: SIGNAL_DOWN }}
              mobile={{ width: "100%" }}
            >
              Pre-order FR-2
            </Button>
            <Text style={label}>€349 · Ships 2 December</Text>
          </Row>
        </Column>

        {/* The drawing: the whole plate on a desktop, the two views larger on a phone */}
        <Column style={{ gap: 12 }} mobile={{ gap: 10 }}>
          <Image src={{ src: "https://hyperelements.dev/img/gallery/oyen/fr2-drawing.png", width: 1020, height: 900 }} alt={DRAWING} style={{ width: "100%" }} />
          <Text style={label}>Fig. 1 — FR-2, front and side</Text>
        </Column>

        {railed(
          "What’s on it",
          <Column>
            {callout(1, "Capsules that turn", "X/Y for the scene in front of you, A/B for the room around you. A quarter turn sets them, and they stay put.")}
            {callout(2, "A hold switch", "Slide it and the buttons sleep while the recording carries on: thirty hours on a charge, on a card of up to 1 TB.")}
            {callout(3, "One dial", "Headphone level, menus and markers. It clicks once per step, so you can work it by feel in the dark.")}
            {callout(4, "Record, always", "It records in 32-bit float, so there’s no gain to set and nothing to clip. A whisper and a door slam both come home whole.")}
          </Column>
        )}

        {railed(
          "Specifications",
          <Table style={{ fontSize: 14, lineHeight: "21px", rowBorder: `1px solid ${RULE}` }}>
            {spec("Recording", "32-bit float, up to 192 kHz", true)}
            {spec("Capsules", "Two cardioids, X/Y or A/B")}
            {spec("Input", "3.5 mm, line or plug-in power")}
            {spec("Battery", "30 hours, USB-C charging")}
            {spec("Storage", "microSD, up to 1 TB")}
            {spec("Size", "132 × 68 × 24 mm, 186 g")}
          </Table>
        )}

        {railed(
          "From the field",
          <Column style={{ gap: 16 }}>
            <Text style={{ fontSize: 24, lineHeight: 1.32, letterSpacing: -0.6 }} mobile={{ fontSize: 22 }}>
              “I left it on a fence post through nine hours of rain. It kept recording, and so did the birds.”
            </Text>
            <Text style={label}>Maren Achterberg, sound recordist</Text>
          </Column>
        )}
      </Section>

      {/* Closing band */}
      <Section style={{ backgroundColor: SIGNAL, padding: [44, 48, 48] }} mobile={{ padding: [36, 24] }}>
        <Row style={{ alignItems: "end", gap: 24 }} mobile={{ gap: 28 }}>
          <Column style={{ gap: 14 }}>
            <Text style={{ ...label, color: INK }}>First run · 2,000 instruments</Text>
            <Heading level={2} style={{ fontSize: 96, lineHeight: 0.9, letterSpacing: -4.5, fontWeight: 500 }} mobile={{ fontSize: 80, letterSpacing: -3.6 }}>
              €349
            </Heading>
            <Text style={{ fontSize: 15, lineHeight: 1.5 }}>Ships 2 December. Charged when it ships.</Text>
          </Column>
          <Column style={{ width: 168 }} mobile={{ width: "100%" }}>
            <Button
              href={`${SITE}/fr-2`}
              style={{ width: "100%", backgroundColor: INK, color: PAPER, fontSize: 15, fontWeight: 600, padding: [16, 20], borderRadius: 2 }}
              hover={{ backgroundColor: "#3A3833" }}
            >
              Pre-order FR-2
            </Button>
          </Column>
        </Row>
      </Section>

      {/* Footer */}
      <Section style={{ padding: [32, 48, 56] }} mobile={{ padding: [28, 24, 44] }}>
        <Row style={{ gap: 24 }} mobile={{ gap: 12 }}>
          <Column style={{ width: RAIL }}>
            <Text style={{ fontSize: 13, fontWeight: 700, letterSpacing: 4 }}>OYEN</Text>
          </Column>
          <Column style={{ gap: 8 }}>
            <Text style={{ fontSize: 13, lineHeight: 1.6, color: QUIET }}>
              Oyen Instruments AS, Møllergata 9, 0179 Oslo. You’re getting dispatches because you asked for them when you bought an Oyen instrument.
            </Text>
            <Text style={{ fontSize: 13, lineHeight: 1.6, color: QUIET }}>
              <Link href={`${SITE}/dispatch/07`} style={{ color: INK }}>
                View online
              </Link>
              {"  ·  "}
              <Link href={`${SITE}/unsubscribe`} style={{ color: INK }}>
                Unsubscribe
              </Link>
            </Text>
          </Column>
        </Row>
      </Section>
    </Email>
  );
}

pell-ashby-invoice.source:
/**
 * Pell & Ashby (a fictional London architecture practice) invoices a client for a stage of work,
 * with the hours behind it on a second page.
 *
 * A printed page, so white paper, black ink and one bottle green, kept for the amount owed and
 * the charts. Newsreader for the words and every figure (its figures are tabular, so a column of
 * amounts lines up), Hanken Grotesk in small capitals for the labels. Everything hangs from four
 * columns: the dates, the addresses and the table's figures all start on them.
 */
import type { ReactNode } from "react";
import { Column, Document, Grid, Heading, LineBreak, PageFooter, PageNumber, Text, Rect, Row, Span, Svg, Table, TableCell, TableRow } from "@hyper-elements/react";

const INK = "#1C1B19";
const QUIET = "#6B675F";
const RULE = "#DAD6CD";
const GREEN = "#24513D";
const SAGE = "#B9C7BC";

const SERIF = "Newsreader, Georgia, 'Times New Roman', serif";
const SANS = "'Hanken Grotesk', 'Helvetica Neue', Helvetica, Arial, sans-serif";

/** A4 at 96 px to the inch, less the side margins: the width everything lays out in. */
const WIDTH = 665;
const GAP = 24;
/** Two of the four columns and the gap between them. */
const HALF = (WIDTH - GAP) / 2;

/** Small capitals in the sans: every label. */
const label = { fontFamily: SANS, fontSize: 9.5, fontWeight: 600, lineHeight: 1.4, letterSpacing: 1.1, textTransform: "uppercase", color: QUIET } as const;

/** A label over a value, the dates' and the addresses' unit. */
const field = (name: string, value: ReactNode, accent = false) => (
  <Column style={{ gap: 6 }}>
    <Text style={label}>{name}</Text>
    <Text style={{ fontSize: 14, lineHeight: 1.45, color: accent ? GREEN : INK, fontWeight: accent ? 600 : 400 }}>{value}</Text>
  </Column>
);

const hairline = (color = RULE) => `1px solid ${color}`;

/** A line of the invoice: what was done, a note under it, and its hours, rate and amount. */
const line = (what: string, note: string, hours: string, rate: string, amount: string) => (
  <TableRow>
    <TableCell style={{ padding: [10, 16, 11, 0], border: { bottom: hairline() } }}>
      {what}
      <LineBreak />
      <Span style={{ fontFamily: SANS, fontSize: 10.5, color: QUIET }}>{note}</Span>
    </TableCell>
    <TableCell style={{ width: 64, padding: [10, 0, 11], textAlign: "right", verticalAlign: "top", border: { bottom: hairline() } }}>{hours}</TableCell>
    <TableCell style={{ width: 72, padding: [10, 0, 11], textAlign: "right", verticalAlign: "top", border: { bottom: hairline() } }}>{rate}</TableCell>
    <TableCell style={{ width: 136, padding: [10, 0, 11], textAlign: "right", verticalAlign: "top", border: { bottom: hairline() } }}>{amount}</TableCell>
  </TableRow>
);

/** A line of the totals, under the hours and rate columns. */
const total = (name: string, amount: string, last = false) => (
  <TableRow>
    <TableCell />
    <TableCell colSpan={2} style={{ padding: last ? [12, 0, 1] : [8, 0], border: last ? { top: hairline(INK) } : undefined, verticalAlign: "bottom", fontSize: last ? 14 : 13.5, color: last ? INK : QUIET }}>
      {name}
    </TableCell>
    <TableCell style={{ padding: last ? [10, 0, 0] : [8, 0], border: last ? { top: hairline(INK) } : undefined, textAlign: "right", verticalAlign: "bottom", fontSize: last ? 26 : 14, lineHeight: last ? 1.1 : 1.45, letterSpacing: last ? -0.3 : 0, color: last ? GREEN : INK }}>
      {amount}
    </TableCell>
  </TableRow>
);

/** A section of the time summary: its label over a rule. */
const part = (name: string, children: ReactNode) => (
  <Column style={{ gap: 16 }}>
    <Text style={{ ...label, color: INK, padding: [0, 0, 8], border: { bottom: hairline(INK) } }}>{name}</Text>
    {children}
  </Column>
);

/** Hours by phase, as horizontal bars beside their names. */
const PHASES: Array<[string, number]> = [
  ["Technical design drawings", 64],
  ["Specification and schedules", 36],
  ["Structural coordination", 22],
  ["Planning conditions", 18],
  ["Site visits and minutes", 16],
];
const HOURS = 156;
const BAR = WIDTH - 196 - 96 - 2 * GAP;
const phase = ([name, hours]: [string, number]) => (
  <Row key={name} style={{ alignItems: "center", gap: GAP }}>
    <Column style={{ width: 196 }}>
      <Text style={{ fontSize: 13.5 }}>{name}</Text>
    </Column>
    <Svg width={BAR} height={10} title={`${hours} hours`}>
      <Rect width={Math.round((hours / 64) * BAR)} height={10} style={{ fill: hours === 64 ? GREEN : SAGE }} />
    </Svg>
    <Column style={{ width: 96 }}>
      <Text style={{ fontSize: 13.5, textAlign: "right" }}>
        {hours} h <Span style={{ color: QUIET }}>· {Math.round((hours / HOURS) * 100)}%</Span>
      </Text>
    </Column>
  </Row>
);

/** Hours by week, as columns over the weeks' Mondays: drawn in one Svg, its labels in a Grid of as many columns. */
const WEEKS: Array<[string, number]> = [
  ["31 Aug", 14],
  ["7 Sep", 18],
  ["14 Sep", 22],
  ["21 Sep", 20],
  ["28 Sep", 16],
  ["5 Oct", 12],
  ["12 Oct", 19],
  ["19 Oct", 21],
  ["26 Oct", 14],
];
const CHART = 120;
const slot = WIDTH / WEEKS.length;
const weeks = (
  <Column style={{ gap: 10 }}>
    <Svg width={WIDTH} height={CHART + 1} title="Hours by week, from 14 to 22">
      {WEEKS.map(([week, hours], i) => {
        const height = Math.round((hours / 22) * (CHART - 8));
        return <Rect key={week} x={Math.round(i * slot + slot / 2 - 18)} y={CHART - height} width={36} height={height} style={{ fill: hours === 22 ? GREEN : SAGE }} />;
      })}
      <Rect x={0} y={CHART} width={WIDTH} height={1} style={{ fill: INK }} />
    </Svg>
    <Grid columns={WEEKS.length} style={{ gap: 0 }}>
      {WEEKS.map(([week, hours]) => (
        <Text key={week} style={{ textAlign: "center", fontSize: 13.5, lineHeight: 1.35 }}>
          {hours} h
          <LineBreak />
          <Span style={{ fontFamily: SANS, fontSize: 10, color: QUIET }}>{week}</Span>
        </Text>
      ))}
    </Grid>
  </Column>
);

/** A row of the people table. */
const person = (name: string, role: string, hours: number) => (
  <TableRow>
    <TableCell style={{ width: HALF + GAP }}>{name}</TableCell>
    <TableCell style={{ color: QUIET }}>{role}</TableCell>
    <TableCell style={{ width: 64, textAlign: "right" }}>{hours} h</TableCell>
    <TableCell style={{ width: 64, textAlign: "right", color: QUIET }}>{Math.round((hours / HOURS) * 100)}%</TableCell>
  </TableRow>
);

export default function PellAshbyInvoice() {
  return (
    <Document
      size="A4"
      margin={[56, 64, 44, 64]}
      title="Invoice PA-0114, Pell & Ashby"
      lang="en-GB"
      fonts={[
        { family: "Newsreader", src: "https://fonts.gstatic.com/s/newsreader/v26/cY9AfjOCX1hbuyalUrK4397yjIJFJpc.woff2", format: "woff2", weight: "200 800" },
        { family: "Newsreader", src: "https://fonts.gstatic.com/s/newsreader/v26/cY9CfjOCX1hbuyalUrK439vCjohCBJWxZA.woff2", format: "woff2", weight: "200 800", style: "italic" },
        { family: "Hanken Grotesk", src: "https://fonts.gstatic.com/s/hankengrotesk/v12/ieVn2YZDLWuGJpnzaiwFXS9tYtpd59CxCis4.woff2", format: "woff2", weight: "100 900" },
      ]}
      style={{ backgroundColor: "#ffffff", color: INK, fontFamily: SERIF, fontSize: 14, lineHeight: 1.45 }}
    >
      <Document.Page style={{ gap: 40 }}>
        {/* Letterhead */}
        <Row style={{ alignItems: "start", gap: GAP }}>
          <Column style={{ gap: 4 }}>
            <Text style={{ fontSize: 25, fontWeight: 500, letterSpacing: -0.5, lineHeight: 1 }}>Pell & Ashby</Text>
            <Text style={label}>Architects</Text>
          </Column>
          <Column>
            <Text style={{ fontFamily: SANS, fontSize: 10.5, lineHeight: 1.6, color: QUIET, textAlign: "right" }}>
              14 Calvert Mews, London E2 7LL
              <LineBreak />
              +44 20 7946 0321 · studio@pellashby.example
            </Text>
          </Column>
        </Row>

        {/* Title, and who it's to: the address starts on the third of four columns */}
        <Row style={{ alignItems: "end", gap: GAP }}>
          <Column style={{ gap: 12 }}>
            <Heading level={1} style={{ fontSize: 84, fontWeight: 300, lineHeight: 0.95, letterSpacing: -2.5 }}>
              Invoice
            </Heading>
            <Text style={{ fontSize: 18, fontStyle: "italic", color: QUIET, lineHeight: 1.35 }}>
              Hawthorn Lane House, Stage 4
              <LineBreak />1 September to 31 October 2026
            </Text>
          </Column>
          <Column style={{ width: HALF }}>
            {field(
              "Billed to",
              <>
                Clara Wendt, Wendt Family Trust
                <LineBreak />3 Hawthorn Lane, Saffron Walden CB11 4QE
              </>
            )}
          </Column>
        </Row>

        {/* The number, the dates and the amount, on the four columns */}
        <Grid columns={4} style={{ gap: GAP, padding: [12, 0, 0], border: { top: hairline(INK) } }}>
          {field("Invoice", "PA-0114")}
          {field("Issued", "4 November 2026")}
          {field("Due", "4 December 2026")}
          {field("Amount due", "£17,731.20", true)}
        </Grid>

        {/* The work, and what it comes to */}
        <Table style={{ fontSize: 14, lineHeight: 1.45 }}>
          <TableRow header>
            <TableCell style={{ ...label, padding: [0, 0, 8], border: { bottom: hairline(INK) } }}>Work</TableCell>
            <TableCell style={{ ...label, padding: [0, 0, 8], textAlign: "right", border: { bottom: hairline(INK) } }}>Hours</TableCell>
            <TableCell style={{ ...label, padding: [0, 0, 8], textAlign: "right", border: { bottom: hairline(INK) } }}>Rate</TableCell>
            <TableCell style={{ ...label, padding: [0, 0, 8], textAlign: "right", border: { bottom: hairline(INK) } }}>Amount</TableCell>
          </TableRow>
          {line("Technical design drawings", "Plans, sections and elevations at 1:50; key details at 1:5", "64", "£95", "6,080.00")}
          {line("Specification and schedules", "Doors, windows, finishes and ironmongery", "36", "£85", "3,060.00")}
          {line("Structural coordination", "With Hale Engineering: steel frame and foundations", "22", "£95", "2,090.00")}
          {line("Planning conditions", "Materials, landscaping and drainage: conditions 3, 5 and 9", "18", "£95", "1,710.00")}
          {line("Site visits and minutes", "Four visits, 2 September to 28 October", "16", "£95", "1,520.00")}
          {line("Expenses, at cost", "Printing and rail travel; receipts attached", "—", "—", "316.00")}
          {total("Subtotal", "14,776.00")}
          {total("VAT at 20%", "2,955.20")}
          {total("Total due", "£17,731.20", true)}
        </Table>

        {/* How to pay, on the same four columns */}
        <Grid columns={4} style={{ gap: GAP, padding: [12, 0, 0], border: { top: hairline(INK) } }}>
          {field("Pay by transfer", "Within 30 days, please")}
          {field("Account name", "Pell & Ashby Ltd")}
          {field("Sort code · Account", "20-45-77 · 63418820")}
          {field("Reference", "PA-0114")}
        </Grid>
      </Document.Page>

      <Document.Page style={{ gap: 36 }}>
        <Row style={{ alignItems: "end", gap: GAP, padding: [0, 0, 12], border: { bottom: hairline() } }}>
          <Column>
            <Text style={{ fontSize: 17, fontWeight: 500, letterSpacing: -0.3, lineHeight: 1 }}>Pell & Ashby</Text>
          </Column>
          <Column>
            <Text style={{ ...label, textAlign: "right" }}>Invoice PA-0114 · Time summary</Text>
          </Column>
        </Row>

        <Column style={{ gap: 12 }}>
          <Heading level={2} style={{ fontSize: 44, fontWeight: 300, lineHeight: 1.05, letterSpacing: -1.1 }}>
            Where the hours went
          </Heading>
          <Text style={{ fontSize: 17, fontStyle: "italic", lineHeight: 1.45, color: QUIET, maxWidth: 520 }}>
            Stage 4 took 156 hours between 1 September and 31 October. Here they are by phase, by week and by the people who worked them.
          </Text>
        </Column>

        {part("By phase", <Column style={{ gap: 14 }}>{PHASES.map(phase)}</Column>)}
        {part("By week", weeks)}
        {part(
          "By person",
          <Table style={{ fontSize: 14, lineHeight: 1.45, cellPadding: [9, 0], rowBorder: hairline() }}>
            {person("Ines Morrow", "Project architect", 74)}
            {person("Sam Okafor", "Architectural assistant", 34)}
            {person("Hannah Pell", "Director", 28)}
            {person("Oliver Ashby", "Director", 20)}
          </Table>
        )}

        <Text style={{ fontFamily: SANS, fontSize: 10.5, lineHeight: 1.6, color: QUIET, maxWidth: 480 }}>
          Hours are recorded to the quarter hour and rounded here, so the phases add up to the total. The full timesheet is yours on request.
        </Text>
      </Document.Page>

      <PageFooter style={{ padding: [12, 0, 0], border: { top: hairline() } }}>
        <Row style={{ gap: GAP }}>
          <Column>
            <Text style={{ fontFamily: SANS, fontSize: 9.5, color: QUIET }}>Pell & Ashby Architects Ltd · Registered in England and Wales, 09412873 · VAT GB 318 4471 02</Text>
          </Column>
          <Column style={{ width: 64 }}>
            <Text style={{ fontFamily: SANS, fontSize: 9.5, color: QUIET, textAlign: "right" }}>
              <PageNumber /> of <PageNumber total />
            </Text>
          </Column>
        </Row>
      </PageFooter>
    </Document>
  );
}

quarry-welcome.source:
/**
 * Quarry (a fictional hosted database) welcomes someone who has just made their first database.
 *
 * Dark, because its users live in terminals: charcoal, warm off-white text and one acid lime,
 * kept for what to do next (the step numbers, the button, the prompt). IBM Plex Sans for words,
 * IBM Plex Mono for anything you could type. The welcome is a short terminal session, then three
 * numbered steps, then what the free tier holds.
 */
import type { ReactNode } from "react";
import { Button, Column, Email, Grid, Heading, LineBreak, Link, Text, Row, Section, Span } from "@hyper-elements/react";

const NIGHT = "#0E0F10";
const PANEL = "#17191B";
const TEXT = "#ECEAE4";
const QUIET = "#9C9A92";
const RULE = "#2B2D30";
const LIME = "#D4F25A";
const LIME_DOWN = "#C2E040";

const SANS = "'IBM Plex Sans', 'Helvetica Neue', Helvetica, Arial, sans-serif";
const MONO = "'IBM Plex Mono', SFMono-Regular, Menlo, Consolas, monospace";

const SITE = "https://quarry.example";

const mono = { fontFamily: MONO, fontSize: 13, lineHeight: 1.7 } as const;

/** A line typed at the prompt, and what came back. */
const typed = (command: string) => (
  <>
    <Span style={{ color: LIME }}>$ </Span>
    {command}
    <LineBreak />
  </>
);

/** One of the three steps: its number, what to do, and why. */
const step = (n: string, title: string, body: ReactNode) => (
  <Row stackOnMobile={false} style={{ gap: 20, padding: [20, 0], border: { top: `1px solid ${RULE}` } }} mobile={{ gap: 14 }}>
    <Column style={{ width: 32 }}>
      <Text style={{ ...mono, fontSize: 14, color: LIME, lineHeight: "24px" }}>{n}</Text>
    </Column>
    <Column style={{ gap: 4 }}>
      <Heading level={3} style={{ fontSize: 17, fontWeight: 600, lineHeight: "24px" }}>
        {title}
      </Heading>
      <Text style={{ fontSize: 15, lineHeight: 1.6, color: QUIET }}>{body}</Text>
    </Column>
  </Row>
);

/** Code inside a sentence. */
const code = (text: string) => <Span style={{ fontFamily: MONO, fontSize: 14, color: TEXT }}>{text}</Span>;

/** A figure of the free tier. */
const figure = (value: string, unit: string, what: string) => (
  <Column style={{ gap: 4 }}>
    <Text style={{ fontFamily: MONO, fontSize: 28, fontWeight: 500, lineHeight: 1.1, letterSpacing: -0.5 }} mobile={{ fontSize: 22 }}>
      {value}
      <Span style={{ fontSize: 15, color: QUIET }}> {unit}</Span>
    </Text>
    <Text style={{ fontSize: 13, lineHeight: 1.45, color: QUIET }}>{what}</Text>
  </Column>
);

export default function QuarryWelcome() {
  return (
    <Email
      width={600}
      lang="en"
      title="Welcome to Quarry"
      previewText="north-ledger is running in Frankfurt. Three steps from an empty schema to your first answer."
      fonts={[
        { family: "IBM Plex Sans", src: "https://fonts.gstatic.com/s/ibmplexsans/v23/zYXzKVElMYYaJe8bpLHnCwDKr932-G7dytD-Dmu1syxeKYbSB4Zh.woff2", format: "woff2", weight: "100 700" },
        { family: "IBM Plex Mono", src: "https://fonts.gstatic.com/s/ibmplexmono/v20/-F63fjptAgt5VM-kVkqdyU8n1i8q131nj-o.woff2", format: "woff2", weight: 400 },
        { family: "IBM Plex Mono", src: "https://fonts.gstatic.com/s/ibmplexmono/v20/-F6qfjptAgt5VM-kVkqdyU8n3twJwlBFgsAXHNk.woff2", format: "woff2", weight: 500 },
      ]}
      style={{ backgroundColor: NIGHT, color: TEXT, fontFamily: SANS, fontSize: 16, lineHeight: 1.6 }}
    >
      <Section style={{ padding: [40, 48, 56], gap: 48 }} mobile={{ padding: [28, 24, 40], gap: 36 }}>
        <Row stackOnMobile={false} style={{ alignItems: "center" }}>
          <Column style={{ width: 120 }}>
            <Text style={{ fontFamily: MONO, fontSize: 18, fontWeight: 500, letterSpacing: -0.3 }}>
              <Link href={SITE} style={{ color: TEXT, textDecoration: "none" }}>
                quarry<Span style={{ color: LIME }}>_</Span>
              </Link>
            </Text>
          </Column>
          <Column>
            <Text style={{ ...mono, fontSize: 12, color: QUIET, textAlign: "right" }}>north-ledger · eu-central</Text>
          </Column>
        </Row>

        <Column style={{ gap: 20 }}>
          <Text style={{ ...mono, color: QUIET }}>Welcome, Priya.</Text>
          <Heading level={1} style={{ fontSize: 44, fontWeight: 500, lineHeight: 1.08, letterSpacing: -1.4 }} mobile={{ fontSize: 31, letterSpacing: -0.9 }}>
            Your first database
            <LineBreak />
            is running.
          </Heading>
          <Text style={{ fontSize: 18, lineHeight: 1.55, color: QUIET, maxWidth: 470 }} mobile={{ fontSize: 16 }}>
            It’s called <Span style={{ color: TEXT }}>north-ledger</Span>, it lives in Frankfurt, and it’s yours to break. Four commands take you from an empty schema to a shell.
          </Text>
        </Column>

        <Column style={{ backgroundColor: PANEL, border: `1px solid ${RULE}`, borderRadius: 6, padding: [20, 24] }} mobile={{ padding: [16, 16] }}>
          <Text style={{ ...mono, color: TEXT }} mobile={{ fontSize: 12 }}>
            {typed("curl -fsSL quarry.example/i | sh")}
            {typed("quarry login")}
            {typed("quarry link north-ledger")}
            {typed("quarry shell")}
            <Span style={{ color: QUIET }}>north-ledger=&gt; </Span>
            select 'hello' as world;
          </Text>
        </Column>

        <Column>
          {step("01", "Connect from your laptop", <>Run {code("quarry link")} in any project, and your shell gets credentials that expire in an hour. Nothing to paste into a .env file.</>)}
          {step("02", "Load a sample", <>Fill it with two million real journeys from London’s bike hire scheme, so your first queries have something to say.</>)}
          {step("03", "Ask it something", <>Open the console and run the query we left in it. It finds the busiest docking station before 9am, in about forty milliseconds.</>)}
        </Column>

        <Row style={{ alignItems: "center", gap: 24 }} mobile={{ gap: 16 }}>
          <Button
            href={`${SITE}/console/north-ledger`}
            style={{ width: 200, backgroundColor: LIME, color: NIGHT, fontSize: 15, fontWeight: 600, padding: [15, 0], borderRadius: 4 }}
            hover={{ backgroundColor: LIME_DOWN }}
            mobile={{ width: "100%" }}
          >
            Open the console
          </Button>
          <Text style={{ fontSize: 15 }}>
            <Link href={`${SITE}/docs/quickstart`} style={{ color: TEXT }}>
              Or read the quickstart
            </Link>
          </Text>
        </Row>

        <Column style={{ gap: 20, padding: [28, 0, 0], border: { top: `1px solid ${RULE}` } }}>
          <Text style={{ ...mono, fontSize: 12, color: QUIET, letterSpacing: 0.5 }}>WHAT THE FREE TIER HOLDS</Text>
          <Grid columns={3} stackOnMobile={false} style={{ gap: 24 }} mobile={{ gap: 12 }}>
            {figure("10", "GB", "of storage")}
            {figure("1", "bn", "row reads a month")}
            {figure("3", "", "branches to try ideas on")}
          </Grid>
        </Column>

        <Column style={{ gap: 6 }}>
          <Text style={{ fontSize: 16, lineHeight: 1.6 }}>
            If anything gets in your way, reply to this email. It comes to the four of us who answer support, and one of us will write back today.
          </Text>
          <Text style={{ fontSize: 16, color: QUIET }}>Tomás, for the Quarry team</Text>
        </Column>

        <Text style={{ ...mono, fontSize: 12, lineHeight: 1.7, color: QUIET, padding: [24, 0, 0], border: { top: `1px solid ${RULE}` } }}>
          Quarry Data GmbH, Rosenthaler Straße 40, 10178 Berlin
          <LineBreak />
          <Link href={`${SITE}/settings/email`} style={{ color: QUIET }}>
            Email settings
          </Link>
          {"  ·  "}
          <Link href={`${SITE}/unsubscribe`} style={{ color: QUIET }}>
            Unsubscribe
          </Link>
        </Text>
      </Section>
    </Email>
  );
}

saltworks-invitation.source:
/**
 * The Saltworks (a fictional gallery on the Essex coast) invites its list to a private view.
 *
 * A poster first: a band of ultramarine across the window, the show's name and its date set
 * huge in Syne, then the artist's drawing (made in code) on salt white below it, as a print
 * would hang. Instrument Sans for the facts. Ultramarine is the only colour; everything else is
 * salt, ink and a grey.
 */
import type { ReactNode } from "react";
import { Button, Column, Email, Heading, Image, LineBreak, Link, Text, Row, Section, Span } from "@hyper-elements/react";

const BLUE = "#1F2BB5";
const BLUE_DOWN = "#17208C";
const SALT = "#F2EFE6";
const INK = "#16161D";
const QUIET = "#5E5D66";
const PALE = "#C9CCF2";
const RULE = "#D9D6CC";

const DISPLAY = "Syne, 'Arial Black', 'Helvetica Neue', Arial, sans-serif";
const SANS = "'Instrument Sans', 'Helvetica Neue', Helvetica, Arial, sans-serif";

const SITE = "https://thesaltworks.example";

const label = { fontSize: 12, fontWeight: 600, letterSpacing: 1.6, textTransform: "uppercase" } as const;

/** A line of the visit's details: what, beside its answer. */
const detail = (name: string, value: ReactNode) => (
  <Row style={{ gap: 24, padding: [14, 0], border: { top: `1px solid ${RULE}` } }} mobile={{ gap: 4 }}>
    <Column style={{ width: 132 }}>
      <Text style={{ ...label, color: QUIET, lineHeight: "24px" }}>{name}</Text>
    </Column>
    <Column>
      <Text style={{ fontSize: 16, lineHeight: "24px" }}>{value}</Text>
    </Column>
  </Row>
);

/** An event in the show's run. */
const event = (date: string, time: string, what: string) => (
  <Row stackOnMobile={false} style={{ gap: 20, padding: [16, 0], border: { top: `1px solid ${RULE}` } }} mobile={{ gap: 14 }}>
    <Column style={{ width: 84 }}>
      <Text style={{ fontFamily: DISPLAY, fontSize: 20, fontWeight: 700, lineHeight: 1.1, color: BLUE }}>
        {date}
        <LineBreak />
        <Span style={{ fontFamily: SANS, fontSize: 13, fontWeight: 400, color: QUIET }}>{time}</Span>
      </Text>
    </Column>
    <Column>
      <Text style={{ fontSize: 16, lineHeight: 1.5 }}>{what}</Text>
    </Column>
  </Row>
);

export default function SaltworksInvitation() {
  return (
    <Email
      width={600}
      lang="en-GB"
      title="Low Water: a private view"
      previewText="Ines Kerr's drawings of the Stour estuary at low tide. Private view on Thursday 20 November, 6 to 9pm."
      fonts={[
        { family: "Syne", src: "https://fonts.gstatic.com/s/syne/v24/8vIH7w4qzmVxm2BL9G78HEY.woff2", format: "woff2", weight: "400 800" },
        { family: "Instrument Sans", src: "https://fonts.gstatic.com/s/instrumentsans/v4/pxiTypc9vsFDm051Uf6KVwgkfoSxQ0GsQv8ToedPibnr0SZe1ZuWi3g.woff2", format: "woff2", weight: "400 700" },
      ]}
      style={{ backgroundColor: SALT, color: INK, fontFamily: SANS, fontSize: 16, lineHeight: 1.6 }}
    >
      {/* The poster */}
      <Section style={{ backgroundColor: BLUE, color: "#FFFFFF", padding: [36, 48, 44], gap: 40 }} mobile={{ padding: [24, 24, 32], gap: 32 }}>
        <Row stackOnMobile={false} style={{ alignItems: "center" }}>
          <Column>
            <Text style={{ ...label, color: "#FFFFFF" }}>
              <Link href={SITE} style={{ color: "#FFFFFF", textDecoration: "none" }}>
                The Saltworks
              </Link>
            </Text>
          </Column>
          <Column>
            <Text style={{ ...label, color: PALE, textAlign: "right" }}>Harwich, Essex</Text>
          </Column>
        </Row>
        <Column style={{ gap: 14 }}>
          <Text style={{ ...label, color: PALE }}>You’re invited to a private view</Text>
          <Heading level={1} style={{ fontFamily: DISPLAY, fontSize: 96, fontWeight: 800, lineHeight: 0.9, letterSpacing: -4 }} mobile={{ fontSize: 64, letterSpacing: -2.5 }}>
            Low
            <LineBreak />
            Water
          </Heading>
          <Text style={{ fontSize: 22, lineHeight: 1.3 }} mobile={{ fontSize: 19 }}>
            New drawings by Ines Kerr
          </Text>
        </Column>
        <Row style={{ alignItems: "end", gap: 20, padding: [20, 0, 0], border: { top: `1px solid ${PALE}` } }} mobile={{ gap: 16 }}>
          <Column style={{ width: 280 }}>
            <Text style={{ fontFamily: DISPLAY, fontSize: 116, fontWeight: 800, lineHeight: 0.8, letterSpacing: -5 }} mobile={{ fontSize: 96, letterSpacing: -4 }}>
              20
            </Text>
          </Column>
          <Column style={{ gap: 2 }}>
            <Text style={{ fontFamily: DISPLAY, fontSize: 26, fontWeight: 700, lineHeight: 1.05 }} mobile={{ fontSize: 24 }}>
              Thursday
              <LineBreak />
              November
            </Text>
            <Text style={{ fontSize: 16, color: PALE }}>
              6 to 9pm, music from 7
            </Text>
          </Column>
        </Row>
      </Section>

      {/* The drawing, hung like a print, with its label */}
      <Section style={{ padding: [48, 48, 0], gap: 12 }} mobile={{ padding: [32, 24, 0], gap: 10 }}>
        <Image
          src={{ src: "https://hyperelements.dev/img/gallery/saltworks/low-water.png", width: 1200, height: 680 }}
          alt="A drawing of a mudflat at low tide: dozens of fine blue lines running to the horizon, closer together as they go, with a low sun on the horizon."
          style={{ width: "100%" }}
        />
        <Text style={{ fontSize: 13, lineHeight: 1.5, color: QUIET }}>
          Ines Kerr, <Span style={{ fontStyle: "italic" }}>Low Water (Stour, 6.14am)</Span>, 2026. Ink on paper, 76 × 43 cm.
        </Text>
      </Section>

      {/* About the show, and the visit */}
      <Section style={{ padding: [40, 48, 0], gap: 28 }} mobile={{ padding: [32, 24, 0], gap: 24 }}>
        <Text style={{ fontSize: 19, lineHeight: 1.55 }} mobile={{ fontSize: 17 }}>
          For a year, Ines walked out onto the Stour estuary at every low tide she could reach before work, and drew what the water left behind. These are thirty-one of those drawings, shown
          together for the first time.
        </Text>
        <Column style={{ border: { bottom: `1px solid ${RULE}` } }}>
          {detail("When", "Thursday 20 November, 6 to 9pm")}
          {detail(
            "Where",
            <>
              The Saltworks, 2 Quay Lane
              <LineBreak />
              Harwich CO12 3HH
            </>
          )}
          {detail("Getting here", "Six minutes’ walk from Harwich Town station. The last train to London is at 22:04.")}
          {detail("Access", "Step-free throughout, with an accessible toilet on the ground floor.")}
        </Column>
        <Row style={{ alignItems: "center", gap: 24 }} mobile={{ gap: 16 }}>
          <Button
            href={`${SITE}/low-water/rsvp`}
            style={{ width: 200, backgroundColor: BLUE, color: "#FFFFFF", fontSize: 15, fontWeight: 600, padding: [16, 0], borderRadius: 0 }}
            hover={{ backgroundColor: BLUE_DOWN }}
            mobile={{ width: "100%" }}
          >
            Reply to say you’ll come
          </Button>
          <Text style={{ fontSize: 15 }}>
            <Link href={`${SITE}/low-water/calendar.ics`} style={{ color: INK }}>
              Add it to your calendar
            </Link>
          </Text>
        </Row>
      </Section>

      {/* The run */}
      <Section style={{ padding: [48, 48, 0], gap: 6 }} mobile={{ padding: [40, 24, 0] }}>
        <Text style={{ ...label, color: QUIET, padding: [0, 0, 8] }}>During the show, until 18 January</Text>
        <Column style={{ border: { bottom: `1px solid ${RULE}` } }}>
          {event("22 Nov", "2pm", "Ines in conversation with Dafydd Rees, who has kept the Harwich tide gauge for thirty years.")}
          {event("7 Dec", "10am", "A drawing walk along the estuary at low tide. Bring boots; we’ll bring the paper.")}
          {event("15 Jan", "6pm", "A late opening, and the last chance to see the drawings together.")}
        </Column>
      </Section>

      <Section style={{ padding: [48, 48, 56] }} mobile={{ padding: [40, 24, 44] }}>
        <Text style={{ fontSize: 13, lineHeight: 1.6, color: QUIET }}>
          The Saltworks is open Wednesday to Sunday, 11am to 5pm, and free. You’re getting this because you’re on our list for openings.{" "}
          <Link href={`${SITE}/unsubscribe`} style={{ color: QUIET }}>
            Leave the list
          </Link>
          .
        </Text>
      </Section>
    </Email>
  );
}

shipwright-ticket.source:
/**
 * Shipwright (a fictional one-day conference on developer tools) sends an attendee their ticket, as
 * a PDF to print or show at the door.
 *
 * The ticket is the top of the page: a deep indigo panel with the event, the date and the venue, and
 * a coral stub with who it's for and a code to scan, the way a printed ticket tears off. Under it,
 * what an attendee looks for on the day: the schedule, how to get there, and what to bring. Space
 * Grotesk for the words, JetBrains Mono for times, codes and labels.
 */
import { Column, Document, Grid, Heading, List, ListItem, PageFooter, Path, Rect, Row, Span, Svg, Table, TableCell, TableRow, Text } from "@hyper-elements/react";

const INDIGO = "#1B1640";
const CORAL = "#FF6B4A";
const MINT = "#7CF0C4";
const INK = "#16141F";
const QUIET = "#6A6678";
const RULE = "#E4E2EA";
const WHITE = "#FFFFFF";

const SANS = "'Space Grotesk', 'Helvetica Neue', Helvetica, Arial, sans-serif";
const MONO = "'JetBrains Mono', Menlo, Consolas, monospace";

const TICKET = "SW26-0418-K";

/** Small capitals in the mono: every label. */
const label = { fontFamily: MONO, fontSize: 9, fontWeight: 500, letterSpacing: 1.4, textTransform: "uppercase", lineHeight: 1.4 } as const;

/** A label over a value, on the ticket. */
const field = (name: string, value: string, color: string) => (
  <Column style={{ gap: 4 }}>
    <Text style={{ ...label, color }}>{name}</Text>
    <Text style={{ fontSize: 15, fontWeight: 600, lineHeight: 1.3 }}>{value}</Text>
  </Column>
);

/**
 * A stand-in for the ticket's code: a 25 by 25 grid with the three corner squares a scanner finds,
 * filled from the ticket number so it's the same every time. Give it your real QR code (as an Svg
 * or an Image) instead.
 */
const SIZE = 25;
const finder = (x: number, y: number) => (cx: number, cy: number) => {
  const dx = cx - x;
  const dy = cy - y;
  if (dx < 0 || dy < 0 || dx > 6 || dy > 6) return null;
  return dx === 0 || dy === 0 || dx === 6 || dy === 6 || (dx >= 2 && dx <= 4 && dy >= 2 && dy <= 4);
};
const finders = [finder(0, 0), finder(SIZE - 7, 0), finder(0, SIZE - 7)];
const seed = [...TICKET].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7);
const dark = (x: number, y: number) => {
  for (const f of finders) {
    const on = f(x, y);
    if (on !== null) return on;
  }
  // The quiet ring around each corner square stays light.
  if ((x <= 7 && y <= 7) || (x >= SIZE - 8 && y <= 7) || (x <= 7 && y >= SIZE - 8)) return false;
  return ((x * 73856093) ^ (y * 19349663) ^ seed) % 7 < 3;
};
const CODE = Array.from({ length: SIZE * SIZE }, (_, i) => [i % SIZE, Math.floor(i / SIZE)])
  .filter(([x, y]) => dark(x, y))
  .map(([x, y]) => `M${x} ${y}h1v1h-1z`)
  .join("");

/** The day, in order: when, what, and where. */
const DAY: Array<[string, string, string]> = [
  ["08:30", "Doors, badges and coffee", "Hall"],
  ["09:30", "Opening keynote: the tools we wish we had", "Main stage"],
  ["10:30", "Shipping a CLI people actually enjoy", "Main stage"],
  ["11:30", "Workshop: your first language server", "Room B"],
  ["13:00", "Lunch on the terrace", "Terrace"],
  ["14:00", "Lightning talks", "Main stage"],
  ["16:30", "Closing panel, then drinks", "Main stage"],
];

export default function ShipwrightTicket() {
  return (
    <Document
      size="A4"
      margin={[48, 56, 40, 56]}
      title={`Shipwright Conf 2026, ticket ${TICKET}`}
      lang="en"
      fonts={[
        { family: "Space Grotesk", src: "https://fonts.gstatic.com/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4C_k3HqU.woff2", format: "woff2", weight: "300 700" },
        { family: "JetBrains Mono", src: "https://fonts.gstatic.com/s/jetbrainsmono/v24/tDbv2o-flEEny0FZhsfKu5WU4zr3E_BX0PnT8RD8yKwBNntkaToggR7BYRbKPxDcwgknk-4.woff2", format: "woff2", weight: "400 700" },
      ]}
      style={{ backgroundColor: WHITE, color: INK, fontFamily: SANS, fontSize: 13, lineHeight: 1.5, gap: 36 }}
    >
      {/* The ticket: the event on the left, who it's for and the code on the stub. */}
      <Row style={{ borderRadius: 16, overflow: "hidden", alignItems: "stretch" }}>
        <Column style={{ backgroundColor: INDIGO, color: WHITE, padding: [28, 30], gap: 22 }}>
          <Row style={{ alignItems: "center", justifyContent: "space-between" }}>
            <Text style={{ flex: "none", fontFamily: MONO, fontSize: 12, fontWeight: 700, letterSpacing: 3 }}>SHIPWRIGHT</Text>
            <Text style={{ flex: "none", ...label, color: INDIGO, backgroundColor: MINT, padding: [4, 10], borderRadius: 999 }}>Admit one</Text>
          </Row>
          <Column style={{ gap: 8 }}>
            <Heading level={1} style={{ fontSize: 40, fontWeight: 700, lineHeight: 1.02, letterSpacing: -1 }}>
              Shipwright Conf 2026
            </Heading>
            <Text style={{ fontSize: 14, lineHeight: 1.45, color: "#CFCBE6" }}>A day of talks on the tools developers build for each other.</Text>
          </Column>
          <Grid columns={3} style={{ gap: 16 }}>
            {field("Date", "Thu 12 March", MINT)}
            {field("Doors", "08:30 WET", MINT)}
            {field("Venue", "Armazém 16", MINT)}
          </Grid>
        </Column>
        <Column style={{ width: 200, backgroundColor: CORAL, color: INDIGO, padding: [28, 24], gap: 16, border: { left: `2px dashed ${INDIGO}` } }}>
          <Column style={{ gap: 4 }}>
            <Text style={label}>Attendee</Text>
            <Text style={{ fontSize: 17, fontWeight: 700, lineHeight: 1.2 }}>Ada Okafor</Text>
            <Text style={{ fontSize: 11.5, lineHeight: 1.3 }}>General admission</Text>
          </Column>
          <Svg width={148} height={148} viewBox={`-2 -2 ${SIZE + 4} ${SIZE + 4}`} title={`The ticket's code, ${TICKET}, to scan at the door.`}>
            <Rect x={-2} y={-2} width={SIZE + 4} height={SIZE + 4} rx={1.5} style={{ fill: WHITE }} />
            <Path d={CODE} style={{ fill: INDIGO }} />
          </Svg>
          <Text style={{ fontFamily: MONO, fontSize: 11, fontWeight: 700, letterSpacing: 1 }}>{TICKET}</Text>
        </Column>
      </Row>

      {/* The day. */}
      <Column style={{ gap: 12 }}>
        <Text style={{ ...label, color: QUIET }}>Your day</Text>
        <Table style={{ rowBorder: `1px solid ${RULE}`, cellPadding: [9, 0] }}>
          {DAY.map(([time, what, where]) => (
            <TableRow key={time}>
              <TableCell style={{ width: 72, fontFamily: MONO, fontSize: 12, fontWeight: 700, color: CORAL }}>{time}</TableCell>
              <TableCell style={{ fontSize: 13.5, fontWeight: 500 }}>{what}</TableCell>
              <TableCell style={{ width: 110, textAlign: "right", fontFamily: MONO, fontSize: 11, color: QUIET }}>{where}</TableCell>
            </TableRow>
          ))}
        </Table>
      </Column>

      {/* Getting there, and what to bring. */}
      <Row style={{ gap: 28, alignItems: "start" }}>
        <Column style={{ gap: 10, backgroundColor: "#F6F5FA", padding: [18, 20], borderRadius: 12 }}>
          <Text style={{ ...label, color: QUIET }}>Getting there</Text>
          <Text style={{ fontSize: 13.5, fontWeight: 600, lineHeight: 1.4 }}>
            Armazém 16
            <Span style={{ fontWeight: 400, color: QUIET }}> · Rua Pereira Henriques 16, 1950-242 Lisbon</Span>
          </Text>
          <Text style={{ fontSize: 12.5, lineHeight: 1.5, color: QUIET }}>
            Metro to Cais do Sodré, then the 15E tram to Pavilhão. Two minutes' walk from the stop, by the river.
          </Text>
        </Column>
        <Column style={{ gap: 10, padding: [18, 0] }}>
          <Text style={{ ...label, color: QUIET }}>Good to know</Text>
          <List style={{ gap: 6, fontSize: 12.5, lineHeight: 1.45, indent: 16 }}>
            <ListItem>Show this ticket on your phone or printed.</ListItem>
            <ListItem>Bring photo ID that matches the name above.</ListItem>
            <ListItem>Talks are recorded; slides follow next day.</ListItem>
            <ListItem>Wi-Fi: Shipwright, password buildtools.</ListItem>
          </List>
        </Column>
      </Row>

      <PageFooter style={{ padding: [12, 0, 0], border: { top: `1px solid ${RULE}` } }}>
        <Row style={{ gap: 16 }}>
          <Text style={{ fontSize: 10, color: QUIET }}>Shipwright Conf · shipwright.example · hello@shipwright.example</Text>
          <Text style={{ width: 120, textAlign: "right", fontFamily: MONO, fontSize: 10, color: QUIET }}>{TICKET}</Text>
        </Row>
      </PageFooter>
    </Document>
  );
}

slow-signals-card.source:
/**
 * Slow Signals (a fictional podcast about quiet work) shares an episode: its social card, 1200 by
 * 630, written as a PNG by @hyper-elements/react/image.
 *
 * Night at sea: a warm near-black, cream type, and the one amber of a lighthouse's beam, drawn
 * with Svg shapes beside the title. DM Serif Display for the title, DM Mono for the rest.
 */
import { Canvas, Circle, Column, Heading, Line, Path, Polygon, Rect, Row, Svg, Text } from "@hyper-elements/react";

const NIGHT = "#1B1712";
const CREAM = "#F1E8D6";
const DIM = "#A79C88";
const AMBER = "#F2B544";

const SERIF = "'DM Serif Display', Georgia, serif";
const MONO = "'DM Mono', Menlo, monospace";

const label = { fontFamily: MONO, fontSize: 18, letterSpacing: 2.5, textTransform: "uppercase", color: DIM } as const;

/** Stars: small, and fewer near the beam. */
const STARS: Array<[number, number, number]> = [
  [40, 60, 2],
  [96, 30, 1.5],
  [150, 96, 2.5],
  [212, 44, 1.5],
  [300, 22, 2],
  [352, 84, 1.5],
  [30, 170, 1.5],
  [330, 168, 2],
  [270, 120, 1.2],
];

/** The beam's spread: from the lantern at (252, 194), 0 wide, to 150 wide at x = 0. */
const beam = (from: number, to: number) => {
  const half = (x: number) => ((252 - x) / 252) * 75;
  return `${from},${194 - half(from)} ${to},${194 - half(to)} ${to},${194 + half(to)} ${from},${194 + half(from)}`;
};
const BEAM: Array<[number, number, number]> = Array.from({ length: 8 }, (_, i) => [252 - i * 31.5, 252 - (i + 1) * 31.5, 0.34 - i * 0.042]);

export default function SlowSignalsCard() {
  return (
    <Canvas
      width={1200}
      height={630}
      lang="en"
      title="Slow Signals, episode 48: The quiet economics of lighthouses"
      fonts={[
        { family: "DM Serif Display", src: "https://fonts.gstatic.com/s/dmserifdisplay/v17/-nFnOHM81r4j6k0gjAW3mujVU2B2G_Bx0vrx52g.woff2", format: "woff2", weight: 400 },
        { family: "DM Mono", src: "https://fonts.gstatic.com/s/dmmono/v16/aFTU7PB1QTsUX8KYthqQBK6PYK0.woff2", format: "woff2", weight: 400 },
      ]}
      style={{ backgroundColor: NIGHT, color: CREAM, fontFamily: MONO, padding: [64, 72], justifyContent: "space-between" }}
    >
      <Row style={{ gap: 48, alignItems: "stretch" }}>
        <Column style={{ gap: 28, justifyContent: "space-between", height: 502 }}>
          <Text style={label}>Slow Signals · Episode 48</Text>
          <Column style={{ gap: 22 }}>
            <Heading level={1} style={{ fontFamily: SERIF, fontSize: 84, fontWeight: 400, lineHeight: 0.98, letterSpacing: -1.5 }}>
              The quiet economics of lighthouses
            </Heading>
            <Text style={{ fontSize: 20, lineHeight: 1.5, color: CREAM }}>With Hannah Okoye, who kept the Fair Isle South light for twenty-three years.</Text>
          </Column>
          <Row style={{ gap: 32, alignItems: "center" }}>
            <Text style={{ ...label, color: AMBER, flex: "none" }}>52 min</Text>
            <Text style={label}>Wherever you listen</Text>
          </Row>
        </Column>
        <Svg width={360} height={502} viewBox="0 0 360 502" title="A lighthouse at night, its beam sweeping out to the left over a dark sea, under a few stars.">
          {STARS.map(([cx, cy, r]) => (
            <Circle key={`${cx}-${cy}`} cx={cx} cy={cy} r={r} style={{ fill: CREAM, opacity: 0.7 }} />
          ))}
          {/* The beam: a wedge from the lantern, fading in steps as it goes. */}
          {BEAM.map(([from, to, opacity]) => (
            <Polygon key={from} points={beam(from, to)} style={{ fill: AMBER, opacity }} />
          ))}
          {/* The tower, its gallery and lantern. */}
          <Polygon points="228,430 240,214 264,214 276,430" style={{ fill: CREAM }} />
          <Polygon points="230,400 232,370 272,370 274,400" style={{ fill: NIGHT, opacity: 0.85 }} />
          <Polygon points="234,320 236,296 268,296 270,320" style={{ fill: NIGHT, opacity: 0.85 }} />
          <Rect x={232} y={206} width={40} height={8} style={{ fill: CREAM }} />
          <Rect x={238} y={180} width={28} height={26} rx={2} style={{ fill: AMBER }} />
          <Path d="M234 182 L252 160 L270 182 Z" style={{ fill: CREAM }} />
          <Line x1={252} y1={160} x2={252} y2={148} style={{ stroke: CREAM, strokeWidth: 2 }} />
          {/* The rock and the sea. */}
          <Path d="M190 436 C214 420 300 418 330 438 L340 452 L180 452 Z" style={{ fill: "#3A332A" }} />
          <Line x1={10} y1={466} x2={150} y2={466} style={{ stroke: AMBER, strokeWidth: 2, opacity: 0.45 }} />
          <Line x1={40} y1={480} x2={120} y2={480} style={{ stroke: AMBER, strokeWidth: 2, opacity: 0.3 }} />
          <Line x1={190} y1={474} x2={340} y2={474} style={{ stroke: DIM, strokeWidth: 1.5, opacity: 0.4 }} />
          <Line x1={220} y1={490} x2={300} y2={490} style={{ stroke: DIM, strokeWidth: 1.5, opacity: 0.3 }} />
        </Svg>
      </Row>
    </Canvas>
  );
}

tarn-shipped.source:
/**
 * Tarn (a fictional pottery in the Pennines) tells a customer their order has shipped.
 *
 * A receipt is calm: one warm white card on stone, Fraunces for the voice, Figtree for the facts,
 * and a celadon green taken from the studio's glaze. Each piece is shown as its glaze, a circle,
 * as a bowl looks from above, instead of a photograph. The parcel's progress is four thin bars.
 */
import { Button, Column, Email, Heading, LineBreak, Link, Text, Row, Section, Span } from "@hyper-elements/react";

const STONE = "#ECE7DF";
const CARD = "#FFFDF9";
const INK = "#2A2522";
const QUIET = "#6E655D";
const RULE = "#E6DFD5";
const CELADON = "#3E6B61";
const CELADON_DOWN = "#2F554D";

const SERIF = "Fraunces, Georgia, 'Times New Roman', serif";
const SANS = "Figtree, 'Helvetica Neue', Helvetica, Arial, sans-serif";

const SITE = "https://tarn.example";

const label = { fontSize: 12, fontWeight: 600, letterSpacing: 1.4, textTransform: "uppercase", color: QUIET } as const;

/** A step of the parcel's journey: a bar, done or not, over its name and date. */
const step = (name: string, date: string, done: boolean) => (
  <Column style={{ gap: 10 }}>
    <Column style={{ height: 4, backgroundColor: done ? CELADON : RULE }} />
    <Text style={{ fontSize: 13, lineHeight: 1.35, color: done ? INK : QUIET, fontWeight: done ? 600 : 400 }} mobile={{ fontSize: 12 }}>
      {name}
      <Span style={{ fontWeight: 400, color: QUIET }}>
        <LineBreak />
        {date}
      </Span>
    </Text>
  </Column>
);

/** A piece in the parcel: its glaze as a circle, what it is, and what it cost. */
const piece = (glaze: string, rim: string, name: string, detail: string, price: string) => (
  <Row stackOnMobile={false} style={{ alignItems: "center", gap: 20, padding: [16, 0], border: { top: `1px solid ${RULE}` } }} mobile={{ gap: 14 }}>
    <Column style={{ width: 48, height: 48, backgroundColor: glaze, borderRadius: 24, border: `1px solid ${rim}` }} />
    <Column style={{ gap: 2 }}>
      <Text style={{ fontFamily: SERIF, fontSize: 18, lineHeight: 1.3 }} mobile={{ fontSize: 16 }}>
        {name}
      </Text>
      <Text style={{ fontSize: 13, color: QUIET }}>{detail}</Text>
    </Column>
    <Column style={{ width: 68 }}>
      <Text style={{ fontSize: 15, textAlign: "right" }}>{price}</Text>
    </Column>
  </Row>
);

/** A line of the totals. */
// The name's line is shorter than the total's, so their baselines meet at the bottom of the row.
const sum = (name: string, amount: string, total = false) => (
  <Row stackOnMobile={false} style={{ alignItems: "end" }}>
    <Column>
      <Text style={{ fontSize: total ? 15 : 14, lineHeight: total ? "19px" : "22px", color: total ? INK : QUIET, fontWeight: total ? 600 : 400 }}>{name}</Text>
    </Column>
    <Column style={{ width: 120 }}>
      <Text style={{ textAlign: "right", fontFamily: total ? SERIF : SANS, fontSize: total ? 24 : 14, lineHeight: total ? "26px" : "22px" }}>{amount}</Text>
    </Column>
  </Row>
);

export default function TarnShipped() {
  return (
    <Email
      width={600}
      lang="en-GB"
      title="Your Tarn order has shipped"
      previewText="Rowan packed your three pieces this morning. They should reach you on Monday."
      fonts={[
        { family: "Fraunces", src: "https://fonts.gstatic.com/s/fraunces/v38/6NU78FyLNQOQZAnv9bYEvDiIdE9Ea92uemAk_WBq8U_9v0c2Wa0KxC9TeP2Xz5c.woff2", format: "woff2", weight: "100 900" },
        { family: "Fraunces", src: "https://fonts.gstatic.com/s/fraunces/v38/6NU58FyLNQOQZAnv9ZwNjucMHVn85Ni7emAe9lKqZTnbB-gzTK0K1ChjeveQ7ZXk8g.woff2", format: "woff2", weight: "100 900", style: "italic" },
        { family: "Figtree", src: "https://fonts.gstatic.com/s/figtree/v9/_Xms-HUzqDCFdgfMm4S9DaRvzig.woff2", format: "woff2", weight: "300 900" },
      ]}
      style={{ backgroundColor: STONE, color: INK, fontFamily: SANS, fontSize: 16, lineHeight: 1.6 }}
    >
      <Section style={{ padding: [40, 0, 48], gap: 24 }} mobile={{ padding: [20, 12, 32], gap: 20 }}>
        <Row stackOnMobile={false} style={{ alignItems: "end", padding: [0, 8] }} mobile={{ padding: [0, 12] }}>
          <Column>
            <Text style={{ fontFamily: SERIF, fontSize: 30, fontStyle: "italic", lineHeight: 1, letterSpacing: -0.5 }}>
              <Link href={SITE} style={{ color: INK, textDecoration: "none" }}>
                Tarn
              </Link>
            </Text>
          </Column>
          <Column>
            <Text style={{ ...label, textAlign: "right" }}>Order TC-20418</Text>
          </Column>
        </Row>

        <Column style={{ backgroundColor: CARD, borderRadius: 4, padding: [48, 48, 40], gap: 36 }} mobile={{ padding: [32, 22, 28], gap: 28 }}>
          <Column style={{ gap: 16 }}>
            <Text style={label}>Shipped 5 November</Text>
            <Heading level={1} style={{ fontFamily: SERIF, fontSize: 42, fontWeight: 400, lineHeight: 1.08, letterSpacing: -1 }} mobile={{ fontSize: 32, letterSpacing: -0.6 }}>
              Packed in straw,
              <LineBreak />
              and <Span style={{ fontStyle: "italic" }}>on its way</Span>.
            </Heading>
            <Text style={{ fontSize: 17, color: QUIET, maxWidth: 440 }} mobile={{ fontSize: 16 }}>
              Rowan wrapped your three pieces this morning. They’re with Parcelforce now, and should reach you on {"Monday 9\u00a0November"}.
            </Text>
          </Column>

          <Row stackOnMobile={false} style={{ gap: 12 }} mobile={{ gap: 8 }}>
            {step("Ordered", "2 Nov", true)}
            {step("Packed", "5 Nov", true)}
            {step("On its way", "5 Nov", true)}
            {step("Delivered", "Mon 9 Nov", false)}
          </Row>

          <Button
            href={`${SITE}/orders/TC-20418/track`}
            style={{ backgroundColor: CELADON, color: "#FFFFFF", fontSize: 15, fontWeight: 600, padding: [15, 28], borderRadius: 2 }}
            hover={{ backgroundColor: CELADON_DOWN }}
            mobile={{ width: "100%" }}
          >
            Follow your parcel
          </Button>

          <Column>
            <Text style={{ ...label, padding: [0, 0, 12] }}>In the box</Text>
            {piece("#B9D2C6", "#9DB9AC", "Tea bowls, celadon", "A pair, 9 cm across", "£64.00")}
            {piece("#EFEBE2", "#D8D1C4", "Serving bowl, ash\u00a0white", "24 cm across", "£58.00")}
            {piece("#3B2A22", "#2A1D17", "Pouring jug, tenmoku", "Holds 600 ml", "£46.00")}
            <Column style={{ gap: 6, padding: [18, 0, 0], border: { top: `1px solid ${INK}` } }}>
              {sum("Subtotal", "£168.00")}
              {sum("Delivery, tracked", "£7.50")}
              {sum("Paid", "£175.50", true)}
            </Column>
          </Column>

          <Row style={{ gap: 24, padding: [24, 0, 0], border: { top: `1px solid ${RULE}` } }} mobile={{ gap: 20 }}>
            <Column style={{ gap: 6 }}>
              <Text style={label}>Delivering to</Text>
              <Text style={{ fontSize: 15, lineHeight: 1.55 }}>
                Ada Whitlock
                <LineBreak />
                14 Rookery Lane, Didsbury
                <LineBreak />
                Manchester M20 6RG
              </Text>
            </Column>
            <Column style={{ gap: 6 }}>
              <Text style={label}>Paid with</Text>
              <Text style={{ fontSize: 15, lineHeight: 1.55 }}>
                Visa ending 0417
                <LineBreak />
                on 2 November 2026
              </Text>
            </Column>
          </Row>

          <Text style={{ fontFamily: SERIF, fontStyle: "italic", fontSize: 16, lineHeight: 1.55, color: QUIET }}>
            Every piece is stoneware, thrown by hand, so yours will differ a little from the ones in the photographs. The bowls are happy in the dishwasher; the jug would rather be washed by hand.
          </Text>
        </Column>

        <Text style={{ fontSize: 13, lineHeight: 1.6, color: QUIET, padding: [0, 8] }} mobile={{ padding: [0, 12] }}>
          Tarn Ceramics, Unit 4, Mytholm Works, Hebden Bridge HX7 6DL. Questions about your order? Reply to this email, or{" "}
          <Link href={`${SITE}/returns`} style={{ color: INK }}>
            read about returns
          </Link>
          .
        </Text>
      </Section>
    </Email>
  );
}

